// Package secretrules finds secret values with the default rules of gitleaks, evaluated by a
// small detector on the standard library's regexp instead of by the gitleaks library (which
// links 60 more modules into the binary and spends about 15 ms building its detector in every
// process). The rules are data, generated by tools/gitleaksrules into rules_gen.go; that tool
// also runs the library and this detector over the same inputs and fails on any difference,
// and testdata/parity.json.gz is the library's recorded answers, checked by this package's tests.
//
// What the library does for a bare string (no file path, no commit, decoding off) is what
// Scan does, step by step:
//
//  1. Keyword prefilter. The text is lower-cased; a rule runs only if one of its keywords
//     (lower-cased) occurs in it as a substring, or if it has no keywords, in which case it
//     always runs. A rule's regex is compiled the first time its prefilter hits.
//  2. Every match of the rule's regex in the text is a candidate. The candidate is the match
//     with leading and trailing newlines trimmed.
//  3. The secret is the candidate, unless the regex has capture groups: the regex is then
//     matched again against the candidate alone (not the text) and the secret is the rule's
//     secretGroup of that match, or the first non-empty group when the rule has none. If the
//     candidate does not match on its own, the whole candidate stays the secret.
//  4. A rule with an entropy needs the secret's Shannon entropy (bits per byte, over runes)
//     to be greater than it.
//  5. The global allowlist, then the rule's allowlists. An allowlist allows the finding when
//     its regexes match their target (the secret, the candidate, or the line holding it) or
//     the lower-cased secret contains a stop word; under condition "and", when both hold if
//     both are given. Allowlist regexes are joined into one alternation, as the library does,
//     so an inline flag like (?i) in one carries into the ones after it.
//
// Paths and commits never apply: every file-path test in the library is false for the empty
// path, which the generator accounts for when it writes the data.
package secretrules

import (
	"math"
	"regexp"
	"sort"
	"strings"
	"sync"
)

// Finding is one value a rule reported.
type Finding struct{ RuleID, Secret string }

// Target is the text an allowlist's regexes are tried on.
type Target uint8

const (
	TargetSecret Target = iota // the secret (the rule's Group, or the match)
	TargetMatch                // the whole regex match
	TargetLine                 // the line holding the match
)

// Rule is a gitleaks rule that can fire on text with no file path.
type Rule struct {
	ID       string
	Regex    string
	Group    int // secretGroup; 0 means the first non-empty capture group, else the match
	Entropy  float64
	Keywords []string // lower case
	Allow    []Allowlist
}

// Allowlist is a gitleaks allowlist reduced to what applies when there is no file path or
// commit: the regexes and stop words (see tools/gitleaksrules for the reduction).
type Allowlist struct {
	And       bool // every present check must hold, rather than any
	Target    Target
	Regexes   []string
	StopWords []string // lower case
}

// Detector scans text with a set of rules. It is safe for concurrent use.
type Detector struct {
	rules  []Rule
	always []int // rules with no keywords
	words  []wordRules
	res    []lazyRegexp
	allow  [][]allowCheck
	global []allowCheck
}

type wordRules struct {
	word  string
	rules []int
}

// lazyRegexp compiles its pattern on first use.
type lazyRegexp struct {
	src  string
	once sync.Once
	re   *regexp.Regexp
}

func (l *lazyRegexp) get() *regexp.Regexp {
	l.once.Do(func() { l.re = regexp.MustCompile(l.src) })
	return l.re
}

type allowCheck struct {
	Allowlist
	joined *lazyRegexp // the regexes as one alternation
}

// New is a detector for rules and a global allowlist. It compiles nothing: a rule's regex is
// compiled when text first contains one of its keywords.
func New(rules []Rule, global []Allowlist) *Detector {
	d := &Detector{rules: rules, res: make([]lazyRegexp, len(rules)), allow: make([][]allowCheck, len(rules))}
	byWord := map[string][]int{}
	for i, r := range rules {
		d.res[i].src = r.Regex
		if len(r.Keywords) == 0 {
			d.always = append(d.always, i)
		}
		for _, k := range r.Keywords {
			k = strings.ToLower(k)
			byWord[k] = append(byWord[k], i)
		}
		for _, a := range r.Allow {
			d.allow[i] = append(d.allow[i], newAllowCheck(a))
		}
	}
	for w, rs := range byWord {
		d.words = append(d.words, wordRules{w, rs})
	}
	for _, a := range global {
		d.global = append(d.global, newAllowCheck(a))
	}
	return d
}

func newAllowCheck(a Allowlist) allowCheck {
	return allowCheck{Allowlist: a, joined: &lazyRegexp{src: "(?:" + strings.Join(a.Regexes, "|") + ")"}}
}

var defaultDetector = sync.OnceValue(func() *Detector { return New(defaultRules, defaultGlobal) })

// Scan is the findings of the default gitleaks rules in s, in rule order. The same value
// found twice is two findings, as in the library.
func Scan(s string) []Finding { return defaultDetector().Scan(s) }

// Scan is the findings of d's rules in s.
func (d *Detector) Scan(s string) []Finding {
	if s == "" {
		return nil
	}
	low := strings.ToLower(s)
	var small [4]uint64
	hit := small[:]
	if len(d.rules) > 64*len(small) {
		hit = make([]uint64, (len(d.rules)+63)/64)
	}
	for _, i := range d.always {
		hit[i/64] |= 1 << (i % 64)
	}
	for _, w := range d.words {
		if strings.Contains(low, w.word) {
			for _, i := range w.rules {
				hit[i/64] |= 1 << (i % 64)
			}
		}
	}
	var out []Finding
	var ln lines
	for i := range d.rules {
		if hit[i/64]&(1<<(i%64)) != 0 {
			out = d.scanRule(out, i, s, &ln)
		}
	}
	return out
}

func (d *Detector) scanRule(out []Finding, i int, s string, ln *lines) []Finding {
	r := &d.rules[i]
	re := d.res[i].get()
	for _, m := range re.FindAllStringIndex(s, -1) {
		match := strings.Trim(s[m[0]:m[1]], "\n")
		start, end := m[0], m[0]+len(match)
		secret := match
		if g := re.FindStringSubmatch(match); len(g) >= 2 {
			if r.Group > 0 {
				if len(g) <= r.Group {
					continue
				}
				secret = g[r.Group]
			} else {
				for _, x := range g[1:] {
					if x != "" {
						secret = x
						break
					}
				}
			}
		}
		if r.Entropy != 0 && entropy(secret) <= r.Entropy {
			continue
		}
		line := func() string { return ln.line(s, start, end) }
		if allowed(d.global, secret, match, line) || allowed(d.allow[i], secret, match, line) {
			continue
		}
		out = append(out, Finding{r.ID, secret})
	}
	return out
}

// allowed reports whether any of the allowlists allows a finding.
func allowed(list []allowCheck, secret, match string, line func() string) bool {
	for i := range list {
		a := &list[i]
		var rx, sw bool
		if len(a.Regexes) > 0 {
			t := secret
			switch a.Target {
			case TargetMatch:
				t = match
			case TargetLine:
				t = line()
			}
			rx = t != "" && a.joined.get().MatchString(t)
		}
		if len(a.StopWords) > 0 && secret != "" {
			low := strings.ToLower(secret)
			for _, w := range a.StopWords {
				if strings.Contains(low, w) {
					sw = true
					break
				}
			}
		}
		if a.And {
			if (len(a.Regexes) == 0 || rx) && (len(a.StopWords) == 0 || sw) {
				return true
			}
		} else if rx || sw {
			return true
		}
	}
	return false
}

// lines finds the line of a match the way the library does, quirks included: a line starts
// at the newline before it (so it begins with "\n" except for the first), and a match after
// the last newline gets the text from the start of s through the end of its line.
type lines struct {
	nl   []int // offsets of "\n" in s
	done bool
}

func (l *lines) line(s string, start, end int) string {
	if !l.done {
		l.done = true
		for i := 0; i < len(s); i++ {
			if s[i] == '\n' {
				l.nl = append(l.nl, i)
			}
		}
	}
	nl := l.nl
	if len(nl) == 0 {
		nl = []int{len(s)}
	}
	from, to, prev, set := 0, 0, 0, false
	for _, n := range nl {
		if prev <= start && start < n {
			set, from, to = true, prev, n
		}
		if prev < end && end <= n {
			to = n
		}
		prev = n
	}
	if !set {
		to = end
		for to < len(s) && s[to] != '\n' && s[to] != '\r' {
			to++
		}
	}
	if end > to {
		to = end
	}
	return s[from:to]
}

// entropy is the Shannon entropy of s in bits, with the library's arithmetic: character
// frequencies are counts over len(s) bytes, summed as freq*log2(freq). The library sums in
// map order; this sums in rune order, which can differ in the last bit and nowhere else.
func entropy(s string) float64 {
	if s == "" {
		return 0
	}
	var ascii [128]int
	var other map[rune]int
	for _, c := range s {
		if c < 128 {
			ascii[c]++
			continue
		}
		if other == nil {
			other = map[rune]int{}
		}
		other[c]++
	}
	inv := 1.0 / float64(len(s))
	var e float64
	for _, n := range ascii {
		if n > 0 {
			f := float64(n) * inv
			e -= f * math.Log2(f)
		}
	}
	if len(other) > 0 {
		runes := make([]rune, 0, len(other))
		for c := range other {
			runes = append(runes, c)
		}
		sort.Slice(runes, func(i, j int) bool { return runes[i] < runes[j] })
		for _, c := range runes {
			f := float64(other[c]) * inv
			e -= f * math.Log2(f)
		}
	}
	return e
}
